describe('toError coercion', () => {
  it('returns the same instance if it is already an Error', () => {
    const error = new Error('already an error');
    expect(toError(error)).toBe(error);
  });

  it('coerces a string to an Error with the string as message and cause', () => {
    const reason = 'string boom';
    const error = toError(reason);
    expect({
      isError: error instanceof Error,
      message: error.message,
      cause: error.cause,
    }).toEqual({
      isError: true,
      message: reason,
      cause: reason,
    });
  });

  it('coerces a plain object with a message property', () => {
    const reason = {message: 'object boom', code: 500};
    const error = toError(reason);
    expect({
      message: error.message,
      cause: error.cause,
    }).toEqual({
      message: 'object boom',
      cause: reason,
    });
  });

  it('coerces a plain object with a detail property', () => {
    const reason = {detail: 'detail boom'};
    const error = toError(reason);
    expect({
      message: error.message,
      cause: error.cause,
    }).toEqual({
      message: 'detail boom',
      cause: reason,
    });
  });

  it('coerces a plain object with neither message nor detail using JSON.stringify', () => {
    const reason = {code: 500};
    const error = toError(reason);
    expect({
      message: error.message,
      cause: error.cause,
    }).toEqual({
      message: JSON.stringify(reason),
      cause: reason,
    });
  });

  it('coerces undefined to an Error', () => {
    const error = toError(undefined);
    expect({
      message: error.message,
      cause: error.cause,
    }).toEqual({
      message: 'undefined',
      cause: undefined,
    });
  });

  it('coerces null to an Error', () => {
    const error = toError(null);
    expect({
      message: error.message,
      cause: error.cause,
    }).toEqual({
      message: 'null',
      cause: null,
    });
  });
});

